// Parse Monday.com webhook payload
// Monday sends: { event: { boardId, pulseId, columnId, value, ... } }
const input = $input.first().json;
const event = input.event || input;

const itemId = String(event.pulseId || event.itemId || input.itemId || '');
const boardId = String(event.boardId || '18399605169');
const statusValue = event.value?.label?.text || event.value?.name || '';

if (!itemId) {
  throw new Error('No item ID found in webhook payload');
}

// Only proceed if status is "New" (trigger appeal generation)
const shouldProcess = statusValue === 'New' || !statusValue;

return [{
  json: {
    item_id: itemId,
    board_id: boardId,
    status_value: statusValue,
    should_process: shouldProcess
  }
}];

// Extract item data from Monday.com response
const response = $input.first().json;
const item = response?.data?.items?.[0];

if (!item) {
  throw new Error('Item not found in Monday.com response');
}

// Parse column values into a usable object
const columns = {};
for (const col of item.column_values || []) {
  columns[col.id] = {
    title: col.title,
    text: col.text,
    value: col.value ? JSON.parse(col.value) : null
  };
}

// Extract key fields
const denialCodeRaw = columns.dropdown_mm0ffjcd?.text || '';
const denialCode = denialCodeRaw.split(' - ')[0]?.trim() || denialCodeRaw;
const denialLabel = denialCodeRaw.split(' - ')[1]?.trim() || '';
const planType = columns.dropdown_mm0fjy49?.text || 'Unknown';
const patientName = item.name.split(' — ')[0]?.trim() || item.name;

return [{
  json: {
    item_id: item.id,
    item_name: item.name,
    patient_name: patientName,
    denial_code: denialCode,
    denial_label: denialLabel,
    dos: columns.date_mm0fp9n1?.text || '',
    denied_amount: columns.numeric_mm0fh3jn?.text || '0',
    plan_type: planType,
    denial_date: columns.date_mm0frn70?.text || '',
    filing_deadline: columns.date_mm0fgzne?.text || '',
    provider: columns.dropdown_mm0fdaya?.text || '',
    location: columns.dropdown_mm0fac7b?.text || '',
    is_fully_insured: planType === 'Fully Insured'
  }
}];

// Build the Gemini appeal drafting prompt
// Combine: classification data + clinical docs + appropriate template
const itemData = $('Extract Item Data').first().json;
const clinicalDocs = $('DrChrono — Fetch Clinical Docs').first().json;

// Select the correct template based on denial code
const templateMap = {
  'PTOT08A': 'appeal_PTOT08A',
  'PTOT05': 'appeal_PTOT05',
  'PTOT21': 'appeal_PTOT21',
  'PTOT19': 'appeal_PTOT19'
};
const templateName = templateMap[itemData.denial_code] || 'appeal_PTOT08A';

// Build classification data JSON for the prompt
const classificationData = {
  classification: {
    denial_code: itemData.denial_code,
    denial_label: itemData.denial_label
  },
  patient: {
    name: itemData.patient_name
  },
  claim: {
    dos_start: itemData.dos,
    denied_amount: itemData.denied_amount,
    denial_date: itemData.denial_date
  },
  payer: {
    name: 'Optum / UnitedHealthcare',
    plan_type: itemData.plan_type
  },
  provider: {
    name: itemData.provider
  },
  filing_deadline: itemData.filing_deadline
};

// Build clinical docs summary
let clinicalSummary = 'Clinical documentation from DrChrono:\n';
if (clinicalDocs && !clinicalDocs.error) {
  clinicalSummary += JSON.stringify(clinicalDocs, null, 2);
} else {
  clinicalSummary += '(Clinical documentation not available — DrChrono API not yet connected. Use placeholder data and list all gaps in missing_documentation.)';
}

// Build the full prompt
const prompt = `SYSTEM PROMPT — PHW Appeal Letter Drafting Agent

You are a medical billing appeal letter specialist for Prestige Health & Wellness (PHW), an out-of-network PT/OT practice in Manhattan, NY. You draft persuasive, evidence-based appeal letters for Optum/UHC denials.

YOUR TASK: Generate a complete, ready-to-send appeal letter using the appropriate template, denial classification data, and clinical documentation from DrChrono.

CONTEXT:
- PHW is an OUT-OF-NETWORK provider — every letter must include AOB reference and OON language
- All letters must include dual escalation path (NY DFS for fully insured, Federal/ERISA for self-funded)
- Letters must cite specific CMS Medicare Benefit Policy Manual sections
- Tone: Professional, firm, evidence-based.

DENIAL CODE: ${itemData.denial_code} — ${itemData.denial_label}
PLAN TYPE: ${itemData.plan_type}

OUTPUT FORMAT: Return a JSON object with: appeal_letter (complete Markdown), summary (2-3 sentences), key_arguments (3-5 bullets), evidence_strength, evidence_assessment, missing_documentation, recommended_actions.

RULES:
- Fill in ALL template variables
- Never fabricate clinical data
- Include specific dates, scores, and measurements from clinical records
- Always include the escalation notice appropriate to the plan type

---
CLASSIFICATION DATA:
${JSON.stringify(classificationData, null, 2)}

CLINICAL DOCUMENTATION:
${clinicalSummary}

TEMPLATE NAME: ${templateName}.md
`;

return [{
  json: {
    prompt,
    item_id: itemData.item_id,
    patient_name: itemData.patient_name,
    denial_code: itemData.denial_code,
    template_name: templateName
  }
}];

// Parse Gemini appeal drafting response
const response = $input.first().json;
const prevData = $('Build Appeal Prompt').first().json;

let text = '';
if (response.candidates && response.candidates[0]) {
  const parts = response.candidates[0].content?.parts || [];
  text = parts.map(p => p.text || '').join('');
}

// Strip markdown code fences
text = text.trim();
if (text.startsWith('```')) text = text.split('\n').slice(1).join('\n');
if (text.endsWith('```')) text = text.slice(0, text.lastIndexOf('```'));
text = text.trim();
if (text.startsWith('json')) text = text.slice(4).trim();

let appeal;
try {
  appeal = JSON.parse(text);
} catch (e) {
  // If JSON parsing fails, treat the whole response as the appeal letter
  appeal = {
    appeal_letter: text,
    summary: `Appeal drafted for ${prevData.patient_name} — ${prevData.denial_code}`,
    key_arguments: [],
    evidence_strength: 'unknown',
    evidence_assessment: 'Could not parse structured response',
    missing_documentation: [],
    recommended_actions: ['Review AI-generated letter manually']
  };
}

return [{
  json: {
    ...prevData,
    appeal_letter: appeal.appeal_letter || '',
    summary: appeal.summary || '',
    key_arguments: appeal.key_arguments || [],
    evidence_strength: appeal.evidence_strength || 'unknown',
    missing_documentation: appeal.missing_documentation || [],
    recommended_actions: appeal.recommended_actions || []
  }
}];

// Build the update to insert appeal text into the Google Doc
// and prepare the Monday.com update
const prevData = $('Parse Appeal Response').first().json;
const docResponse = $input.first().json;

let docUrl = '';
let docId = '';

if (docResponse.documentId) {
  docId = docResponse.documentId;
  docUrl = `https://docs.google.com/document/d/${docId}/edit`;
}

// Build Monday.com column update
const columnValues = {
  // Appeal Status → Drafted
  color_mm0fj7fm: { label: 'Drafted' },
  // Appeal Letter (link)
  link_mm0fsy2k: docUrl ? { url: docUrl, text: 'Appeal Letter' } : {}
};

return [{
  json: {
    ...prevData,
    doc_id: docId,
    doc_url: docUrl,
    column_values: JSON.stringify(columnValues),
    move_to_group: 'group_mm0fhrnr'  // In Progress
  }
}];

// Final response
const data = $('Prepare Monday.com Updates').first().json;

return [{
  json: {
    status: 'success',
    message: `Appeal drafted for ${data.patient_name} — ${data.denial_code}`,
    item_id: data.item_id,
    doc_url: data.doc_url || 'Google Docs not configured',
    evidence_strength: data.evidence_strength,
    recommended_actions: data.recommended_actions
  }
}];
